const Jimp = require('jimp');
const item = $input.item;
const b = item.binary || {};
// Form Trigger stores the uploaded file under the field label; grab data / data_0 / first key.
const key = b.data ? 'data' : (b.data_0 ? 'data_0' : Object.keys(b)[0]);
if (!key) throw new Error('No uploaded file found. Upload an image in the form field "data".');
const img = await Jimp.read(Buffer.from(b[key].data, 'base64'));
const origW = img.bitmap.width, origH = img.bitmap.height;
const pngBuf = await img.getBufferAsync(Jimp.MIME_PNG);
item.binary = { data: { data: pngBuf.toString('base64'), mimeType: 'image/png', fileName: 'input.png' } };
item.json = { origW, origH };
return item;

const Jimp = require('jimp');
const item = $input.item;
const img = await Jimp.read(Buffer.from(item.binary.data.data, 'base64'));
const out = img.resize(1024, 1024);
const buf = await out.getBufferAsync(Jimp.MIME_PNG);
item.binary = { image: { data: buf.toString('base64'), mimeType: 'image/png', fileName: 'image.png' } };
item.json = { targetW: 1024, targetH: 1024 };
return item;

const { PDFDocument } = require('pdf-lib');
const item = $input.item;
const pngBuf = Buffer.from(item.binary.data.data, 'base64');
const pdf = await PDFDocument.create();
const png = await pdf.embedPng(pngBuf);
const page = pdf.addPage([png.width, png.height]);
page.drawImage(png, { x: 0, y: 0, width: png.width, height: png.height });
const bytes = await pdf.save();
item.binary = { data: { data: Buffer.from(bytes).toString('base64'), mimeType: 'application/pdf', fileName: 'original.pdf' } };
item.json = {};
return item;

// Best-effort ABBYY XML parser (with xml:writeFormatting=true) + pixel color sampling.
// ADJUST the regex tag/attribute names to match YOUR ABBYY response if it differs.
const Jimp = require('jimp');

function attr(s, n){ const m = s.match(new RegExp(n + '="([^"]*)"')); return m ? m[1] : null; }

function sampleColor(img, x, y, w, h){
  const W = img.bitmap.width, H = img.bitmap.height;
  x = Math.max(0, Math.floor(x)); y = Math.max(0, Math.floor(y));
  w = Math.min(W - x, Math.ceil(w)); h = Math.min(H - y, Math.ceil(h));
  if (w <= 0 || h <= 0) return { r: 0, g: 0, b: 0 };
  const corners = [[x,y],[x+w-1,y],[x,y+h-1],[x+w-1,y+h-1]];
  let br=0, bgc=0, bb=0;
  for (const [cx,cy] of corners){ const c = Jimp.intToRGBA(img.getPixelColor(cx,cy)); br+=c.r; bgc+=c.g; bb+=c.b; }
  br/=4; bgc/=4; bb/=4;
  const px = [];
  const step = Math.max(1, Math.floor(Math.sqrt((w*h)/400)));
  for (let yy=y; yy<y+h; yy+=step) for (let xx=x; xx<x+w; xx+=step){
    const c = Jimp.intToRGBA(img.getPixelColor(xx,yy));
    const d = Math.abs(c.r-br) + Math.abs(c.g-bgc) + Math.abs(c.b-bb);
    px.push({ c, d });
  }
  if (!px.length) return { r:0, g:0, b:0 };
  px.sort((a,b)=> b.d - a.d);
  const top = px.slice(0, Math.max(1, Math.floor(px.length*0.25)));
  let r=0,g=0,b=0; for (const p of top){ r+=p.c.r; g+=p.c.g; b+=p.c.b; }
  const n = top.length; return { r:Math.round(r/n), g:Math.round(g/n), b:Math.round(b/n) };
}

const xml = $json.data || $json.body || (typeof $json === 'string' ? $json : '');
const norm = $('Normalize').first();
const origImg = await Jimp.read(Buffer.from(norm.binary.data.data, 'base64'));
const origW = norm.json.origW, origH = norm.json.origH;

const words = [];
const fmtRe = /<formatting\b([^>]*)>([\s\S]*?)<\/formatting>/g;
let fm;
while ((fm = fmtRe.exec(xml))){
  const fa = fm[1];
  let inner = fm[2];
  const ff = attr(fa, 'ff');
  const fs = parseFloat(attr(fa, 'fs') || '0');
  const bold = /bold="(1|true)"/i.test(fa);
  const italic = /italic="(1|true)"/i.test(fa);
  // normalize self-closing (space) charParams into an empty word break
  inner = inner.replace(/<charParams\b[^>]*\/>/g, '<charParams> </charParams>');
  const cpRe = /<charParams\b([^>]*)>([\s\S]*?)<\/charParams>/g;
  let cp, cur = null;
  const flush = () => {
    if (cur && cur.text.trim()){
      const col = sampleColor(origImg, cur.l, cur.t, cur.r - cur.l, cur.b - cur.t);
      words.push({ text: cur.text, x: cur.l, y: cur.t, w: cur.r - cur.l, h: cur.b - cur.t,
                   fontSize: fs || null, ff, bold, italic, color: col });
    }
    cur = null;
  };
  while ((cp = cpRe.exec(inner))){
    const ca = cp[1], ch = cp[2];
    const l = +attr(ca,'l'), t = +attr(ca,'t'), r = +attr(ca,'r'), b = +attr(ca,'b');
    if (!ch || /^\s*$/.test(ch)){ flush(); continue; }
    if (!cur) cur = { text: '', l, t, r, b };
    cur.text += ch;
    cur.l = Math.min(cur.l, l); cur.t = Math.min(cur.t, t);
    cur.r = Math.max(cur.r, r); cur.b = Math.max(cur.b, b);
  }
  flush();
}
return [{ json: { words, origW, origH, wordCount: words.length } }];

const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');
const Jimp = require('jimp');

const bgResp = $('OpenAI Edit').first().json;
const bgB64 = bgResp && bgResp.data && bgResp.data[0] && bgResp.data[0].b64_json;
if (!bgB64) throw new Error('No background from OpenAI: ' + JSON.stringify(bgResp).slice(0,300));

const p = $('Parse ABBYY XML').first().json;
const words = p.words || [];
const W = p.origW, H = p.origH;

// upscale the 1024 background back to original size so it aligns with OCR coordinates
const up = (await Jimp.read(Buffer.from(bgB64, 'base64'))).resize(W, H);
const bgBuf = await up.getBufferAsync(Jimp.MIME_PNG);

const pdf = await PDFDocument.create();
const page = pdf.addPage([W, H]);
const bg = await pdf.embedPng(bgBuf);
page.drawImage(bg, { x: 0, y: 0, width: W, height: H });

const cache = {};
async function font(name){ if (!cache[name]) cache[name] = await pdf.embedFont(StandardFonts[name]); return cache[name]; }
function pick(ff, bold, italic){
  const f = (ff || '').toLowerCase();
  let fam = 'H';
  if (/times|serif|georgia|roman|minion|garamond/.test(f)) fam = 'T';
  else if (/courier|mono|consol/.test(f)) fam = 'C';
  if (fam === 'H') return bold&&italic?'HelveticaBoldOblique':bold?'HelveticaBold':italic?'HelveticaOblique':'Helvetica';
  if (fam === 'T') return bold&&italic?'TimesRomanBoldItalic':bold?'TimesRomanBold':italic?'TimesRomanItalic':'TimesRoman';
  return bold&&italic?'CourierBoldOblique':bold?'CourierBold':italic?'CourierOblique':'Courier';
}

for (const wd of words){
  const t = (wd.text || '').trim();
  if (!t) continue;
  const fnt = await font(pick(wd.ff, wd.bold, wd.italic));
  let size = Math.max(4, wd.h * 0.85);
  const tw = fnt.widthOfTextAtSize(t, size);
  if (tw > wd.w && tw > 0) size = Math.max(3, size * (wd.w / tw));
  const c = wd.color || { r:0, g:0, b:0 };
  try {
    page.drawText(t, { x: wd.x, y: H - wd.y - wd.h * 0.85, size, font: fnt,
                       color: rgb(c.r/255, c.g/255, c.b/255) });
  } catch (e) { /* skip unencodable glyphs */ }
}

const bytes = await pdf.save();
const item = $input.item;
item.binary = { pdf: { data: Buffer.from(bytes).toString('base64'), mimeType: 'application/pdf', fileName: 'output.pdf' } };
item.json = { ok: true, words: words.length };
return item;
